import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`solo-rate-optimizer`,heroTitle:`Optimize your solo practice's rates in minutes`,heroSubtitle:`Perplexity Computer reviews your offers, market positioning, and client journey, then builds a pricing plan for stronger revenue and fit.`,inputUrlCta:`Optimize my rates`,inputUrlPlaceholder:`yourpractice.com`,inputUrlPrefill:`Go to {url} and run a pricing optimization analysis for this solo practice. 1) Review current services, packages, consultation language, pricing cues, client segments, and positioning. 2) Benchmark comparable solo practitioners and local or niche competitors for rate ranges, packaging, and proof. 3) Identify underpriced offers, confusing packages, missing anchors, and opportunities for premium tiers or retainers. 4) Recommend rate changes with rationale, risk notes, and rollout messaging. 5) Deliver a pricing action plan with revised package language, client communication drafts, and a 30-day rollout sequence.`,heroOverlaySteps:[`Reviewing current services, packages, pricing cues, and client segments`,`Benchmarking comparable practitioners for rates, packaging, and proof`,`Finding underpriced offers, missing anchors, and premium-tier opportunities`,`Pricing plan, revised package copy, and rollout sequence ready to use`],generatingSteps:[`Visiting {url} to review services, offers, and pricing presentation`,`Designing an agent to benchmark comparable practices and package structures`,`Configuring rate-change recommendations, rollout messaging, and risk notes`,`Packaging the work into a practical pricing optimization plan`],featureSectionTitle:`From pricing guesswork to a clearer rate strategy`,featureCardTitles:[`Connects to your practice data`,`Outputs you can roll out`],featureCardDescriptions:[`Computer breaks pricing work into offer review, competitor benchmarking, package design, and rollout messaging, then routes each step to the right model.`,`Your website, booking pages, spreadsheets, Docs, and CRM notes can feed one workflow so pricing changes are grounded in context.`,`Rate recommendations. Package rewrites. Premium-tier ideas. Client communication drafts. Computer gives you the materials to adjust pricing with less guesswork.`],capabilitySectionTitle:`Your pricing analyst, on demand`,capabilitySectionSubtitle:`Paste your practice site, step away, and come back to rates and packages you can test.`,capabilityCards:[{title:`Offer Review`,description:`Computer can review your services, packages, consultation language, and pricing cues to find gaps in value presentation.`},{title:`Market Benchmarking`,description:`Computer can compare comparable practitioners and competitors for rate ranges, package structures, and proof points.`},{title:`Package Optimization`,description:`Computer can suggest stronger anchors, tiers, retainers, and add-ons that align price with client value.`},{title:`Connect Your Tools`,description:`Computer can organize findings across your website, booking tools, Docs, Sheets, and CRM notes.`},{title:`Remember Your Constraints`,description:`Computer can remember your revenue goals, client mix, and risk tolerance so future pricing work starts from your context.`},{title:`Monitor Pricing Signals`,description:`Computer can revisit competitor positioning and inquiry quality later to recommend the next pricing adjustment.`}]});export{t as default};
